fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // Promote to a larger integer type to avoid potential i8 overflow when summing.
    let r = r as i16;
    let g = g as i16;
    let b = b as i16;

    // Compute the maximum count among the three colors.
    let max_count = r.max(g).max(b);
    // Compute the total number of items.
    let total = r + g + b;

    // The arrangement without two adjacent items of the same color is possible
    // if and only if 2 * max_count <= total + 1.
    2 * max_count <= total + 1
}

