        // One color slightly larger but still feasible
        assert!(check_lamp_arrangement(3, 2, 2)); // 2*3 = 6 <= 7 = total+1
        assert!(!check_lamp_arrangement(4, 1, 1)); // 2*4 = 8 > 7 = total+1

        // Two colors small, one color large
        assert!(!check_lamp_arrangement(6, 1, 1)); // 2*6 = 12 > 8 = total+1

        // Edge of feasibility
